import React, { useState, useEffect } from "react";
import { Star, X, ArrowLeftCircle, ArrowRightCircle } from "lucide-react";

const COLORS = {
  bg: "#04070a",
  panel: "#0a1018",
  panelDark: "#000000",
  text: "#e6f4ff",
  muted: "#4f6a7f",
  blue: "#00baff",
  white: "#ffffff",
  cyan: "#00fff2",
  red: "#ff2e6e",
  gold: "#ffcc00",
  green: "#39ff14",
  win: "#00baff",
  loss: "#ff2e6e",
};

// Color used per variant tier. Add a new `includes` line here if you
// introduce a brand new variant type beyond Normal / Gold / Cheat Master.
function variantColor(name) {
  const n = name.toLowerCase();
  if (n.includes("gold")) return COLORS.gold;
  if (n.includes("cheat")) return COLORS.green;
  if (n.includes("normal")) return COLORS.white;
  return COLORS.blue; // fallback color for any future variant type
}

function slugify(str) {
  return str.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/(^-|-$)/g, "");
}

// ================================================================
// SPRITE DATABASE
// ----------------------------------------------------------------
// To add a NEW BASE SPRITE (e.g. a new item added in a future update):
//   mkBase("New Sprite Name", [V("Normal", 3), V("Gold", 6), V("Cheat Master", 9)]),
//
// To add a NEW VARIANT to an existing sprite, just add another V(...)
// entry to that sprite's array, e.g. V("Rainbow", 10).
//
// Dust Values below are PLACEHOLDERS (3 / 6 / 9) — replace the numbers
// with real values whenever you have them.
// ================================================================
// V(name, dust, image) — image is optional. Leave it off and the sprite
// shows the placeholder [XX] tag; pass an image URL and it renders that
// picture instead.
const V = (name, dust, image) => ({ name, dust, image });

function mkBase(base, variants) {
  const slug = slugify(base);
  return {
    base,
    slug,
    variants: variants.map((v) => ({ ...v, id: `${slug}-${slugify(v.name)}` })),
  };
}

// ----------------------------------------------------------------
// Uploaded sprite images (embedded as base64 so no external hosting
// is needed yet). To add more, give me the image and I will add a
// new const here the same way, then reference it in a V(...) call
// below.
// ----------------------------------------------------------------
const IMG_8BIT_NORMAL = "data:image/png;base64,";
const IMG_8BIT_GOLD = "data:image/png;base64,";
const IMG_8BIT_CHEAT = "data:image/png;base64,";

const IMG_ADV_NORMAL = "data:image/png;base64,";
const IMG_ADV_GOLD = "data:image/png;base64,";
const IMG_ADV_CHEAT = "data:image/png;base64,";
const IMG_BUSH_NORMAL = "data:image/png;base64,";
const IMG_BUSH_GOLD = "data:image/png;base64,";
const IMG_BUSH_CHEAT = "data:image/png;base64,";
const IMG_SHADOW_NORMAL = "data:image/png;base64,";

const IMG_CROWN_CHEAT = "data:image/png;base64,";
const IMG_JACKRABBIT_CHEAT = "data:image/png;base64,";
const IMG_JONESY_CHEAT = "data:image/png;base64,";
const IMG_KILLSWITCH_CHEAT = "data:image/png;base64,";
const IMG_KLOMBO_CHEAT = "data:image/png;base64,";
const IMG_SHADOW_CHEAT = "data:image/png;base64,";
const IMG_SONIC_CHEAT = "data:image/png;base64,";
const IMG_TAILS_CHEAT = "data:image/png;base64,";
const IMG_CROWN_NORMAL = "data:image/png;base64,";
const IMG_CROWN_GOLD = "data:image/png;base64,";
const IMG_JACKRABBIT_GOLD = "data:image/png;base64,";
const IMG_JONESY_GOLD = "data:image/png;base64,";
const IMG_KILLSWITCH_GOLD = "data:image/png;base64,";
const IMG_KLOMBO_GOLD = "data:image/png;base64,";
const IMG_SHADOW_GOLD = "data:image/png;base64,";
const IMG_SONIC_GOLD = "data:image/png;base64,";
const IMG_TAILS_GOLD = "data:image/png;base64,";
const IMG_JACKRABBIT_NORMAL = "data:image/png;base64,";
const IMG_JONESY_NORMAL = "data:image/png;base64,";
const IMG_KILLSWITCH_NORMAL = "data:image/png;base64,";

const IMG_KLOMBO_NORMAL = "data:image/png;base64,";
const IMG_SONIC_NORMAL = "data:image/png;base64,";
