function cardStyle(accent) {
  return {
    background: COLORS.panel,
    border: `1px solid ${accent}`,
    boxShadow: `0 0 10px ${accent}55, inset 0 0 20px ${accent}0d`,
  };
}

function Chip({ id, onRemove }) {
  const v = BY_ID[id];
  const color = variantColor(v.name);
  return (
    <div
      className="flex items-center gap-2 pl-1.5 pr-2 py-1 flex-shrink-0 self-start"
      style={{ background: COLORS.panelDark, border: `1px solid ${color}` }}
    >
      <SpriteVisual image={v.image} base={v.base} color={color} size={24} />
      <span className="term-font" style={{ color: COLORS.text }}>{v.label}</span>
      <span className="term-font" style={{ color: COLORS.gold, fontSize: 12 }}>{v.dust}</span>
      <button onClick={onRemove} style={{ color: COLORS.muted }} aria-label={`Remove ${v.label}`}>
        <X size={13} />
      </button>
    </div>
  );
}

function TradePanel({ title, accent, ids, onRemove, total }) {
  return (
    <div className="flex-1 p-4 flex flex-col gap-3 min-h-[180px]" style={cardStyle(accent)}>
      <div className="flex items-center justify-between">
        <span className="term-font" style={{ color: accent, fontSize: 15, textShadow: `0 0 6px ${accent}` }}>
          &gt; {title}
        </span>
        <span className="term-font" style={{ color: COLORS.muted, fontSize: 12 }}>{ids.length}/5</span>
      </div>
      <div className="flex flex-wrap content-start items-start gap-2 flex-1">
        {ids.length === 0 && (
          <span className="term-font" style={{ color: COLORS.muted, fontSize: 12 }}>
            // awaiting input
          </span>
        )}
        {ids.map((id) => (
          <Chip key={id} id={id} onRemove={() => onRemove(id)} />
        ))}
      </div>
      <div className="flex items-center justify-between pt-3" style={{ borderTop: `1px dashed ${COLORS.muted}66` }}>
        <span className="term-font" style={{ color: COLORS.muted, fontSize: 12 }}>TOTAL_DUST_VALUE</span>
        <span className="term-font" style={{ color: accent, fontSize: 20, textShadow: `0 0 6px ${accent}` }}>{total}</span>
      </div>
    </div>
  );
}

function SpriteCard({ sprite, selectedIdx, onSelect, locker, toggleLocker, addTo }) {
  const variant = sprite.variants[selectedIdx];
  const full = BY_ID[variant.id];
  const color = variantColor(variant.name);
  const starred = locker.has(variant.id);
  return (
    <div className="p-3 flex flex-col gap-2.5" style={cardStyle(color)}>
      <div className="flex items-start justify-between">
        <SpriteVisual image={full.image} base={sprite.base} color={color} size={56} />
        <button onClick={() => toggleLocker(variant.id)} aria-label="Toggle locker">
          <Star size={26} color={COLORS.gold} fill={starred ? COLORS.gold : "none"} style={{ filter: starred ? `drop-shadow(0 0 4px ${COLORS.gold})` : "none" }} />
        </button>
      </div>
      <div>
        <div className="term-font" style={{ color: COLORS.text, fontSize: 15 }}>{full.label}</div>
        <div className="term-font" style={{ color, fontSize: 13 }}>{variant.dust}/10 DUST_VALUE</div>
      </div>
      <div className="flex gap-1.5 flex-wrap">
        {sprite.variants.map((v, i) => {
          const c = variantColor(v.name);
          const active = i === selectedIdx;
          return (
            <button
              key={v.id}
              onClick={() => onSelect(sprite.slug, i)}
              className="term-font"
              style={{
                fontSize: 10,
                padding: "3px 8px",
                background: active ? c : "transparent",
                color: active ? "#000" : c,
                border: `1px solid ${c}`,
                textShadow: active ? "none" : `0 0 4px ${c}`,
              }}
            >
              {v.name}
            </button>
          );
        })}
      </div>
      <div className="flex items-center gap-3 mt-1">
        <button
          onClick={() => addTo("offer", variant.id)}
          title="Add to Offer"
          className="flex items-center justify-center"
          style={{ color: COLORS.cyan, width: 44, height: 44 }}
        >
          <ArrowLeftCircle size={30} strokeWidth={1.8} />
        </button>
        <button
          onClick={() => addTo("receive", variant.id)}
          title="Add to Receive"
          className="flex items-center justify-center"
          style={{ color: COLORS.red, width: 44, height: 44 }}
        >
          <ArrowRightCircle size={30} strokeWidth={1.8} />
        </button>
      </div>
    </div>
  );
}

export default function SpriteDustExchange() {
  const [page, setPage] = useState("home"); // "home" | "privacy" | "terms"
  const [selectedIdx, setSelectedIdx] = useState(() =>
    Object.fromEntries(SPRITES.map((s) => [s.slug, 0]))
  );
  const [locker, setLocker] = useState(new Set(["sonic-cheat-master"]));
  const [lockerLoaded, setLockerLoaded] = useState(false);
  const [offer, setOffer] = useState(["bush-normal"]);
  const [receive, setReceive] = useState(["bush-gold"]);

  // consent: null (not yet decided), "yes", or "no".
  // NOTE: window.storage only works inside this Claude preview. Once this
  // site is hosted for real, replace the bodies of these effects with
  // localStorage.getItem / localStorage.setItem — everything else stays
  // the same.
  const [consent, setConsent] = useState(null);
  const [consentChecked, setConsentChecked] = useState(false);
  const [consentModalOpen, setConsentModalOpen] = useState(false);

  // Check whether this device has already answered the storage question.
  useEffect(() => {
    let cancelled = false;
    (async () => {
      try {
        const result = await window.storage.get("consent", false);
        if (!cancelled && result) setConsent(result.value);
      } catch (err) {
        // no answer saved yet
      } finally {
        if (!cancelled) setConsentChecked(true);
      }
    })();
    return () => { cancelled = true; };
  }, []);

  // Once we know there's no answer on file yet, show the prompt.
  useEffect(() => {
    if (consentChecked && consent === null) setConsentModalOpen(true);
  }, [consentChecked, consent]);

  function answerConsent(allow) {
    const value = allow ? "yes" : "no";
    setConsent(value);
    setConsentModalOpen(false);
    window.storage.set("consent", value, false).catch(() => {});
    if (!allow) {
      // they said no — clear anything saved, and don't keep it in memory either
      window.storage.delete("locker", false).catch(() => {});
      setLocker(new Set());
    }
  }

  // Only load the saved locker if they've said yes.
  useEffect(() => {
    if (consent !== "yes") return;
    let cancelled = false;
    (async () => {
      try {
        const result = await window.storage.get("locker", false);
        if (!cancelled && result) {
          const ids = JSON.parse(result.value);
          setLocker(new Set(ids));
        }
      } catch (err) {
        // no saved locker yet
      } finally {
        if (!cancelled) setLockerLoaded(true);
      }
    })();
    return () => { cancelled = true; };
  }, [consent]);

  // Only save the locker if they've said yes.
  useEffect(() => {
    if (consent !== "yes" || !lockerLoaded) return;
    window.storage.set("locker", JSON.stringify([...locker]), false).catch(() => {});
  }, [locker, lockerLoaded, consent]);


  const offerTotal = offer.reduce((a, id) => a + BY_ID[id].dust, 0);
  const receiveTotal = receive.reduce((a, id) => a + BY_ID[id].dust, 0);
  const diff = receiveTotal - offerTotal;
  const angle = Math.max(-16, Math.min(16, diff * 2.5));

  // Win/loss percentage: how much more (or less) you're receiving vs. offering.
  let percent = 0;
  if (offerTotal === 0 && receiveTotal > 0) percent = 100;
  else if (offerTotal > 0) percent = Math.round((diff / offerTotal) * 100);
  const percentColor = percent > 0 ? COLORS.win : percent < 0 ? COLORS.loss : COLORS.muted;
  const percentLabel = offerTotal === 0 && receiveTotal === 0 ? "--" : `${percent > 0 ? "+" : ""}${percent}%`;

  let verdict, verdictColor;
  if (offerTotal === 0 && receiveTotal === 0) {
    verdict = "AWAITING_INPUT :: ADD SPRITES TO BOTH SIDES";
    verdictColor = COLORS.muted;
  } else if (diff === 0) {
    verdict = "STATUS :: EVEN TRADE";
    verdictColor = COLORS.cyan;
  } else if (diff > 0) {
    verdict = `STATUS :: GAIN +${diff} DUST VALUE`;
    verdictColor = COLORS.win;
  } else {
    verdict = `STATUS :: LOSS -${-diff} DUST VALUE`;
    verdictColor = COLORS.loss;
  }

  function onSelect(slug, i) {
    setSelectedIdx((prev) => ({ ...prev, [slug]: i }));
  }
  function toggleLocker(id) {
    setLocker((prev) => {
      const next = new Set(prev);
      next.has(id) ? next.delete(id) : next.add(id);
      return next;
    });
  }
  const MAX_PER_SIDE = 5;
  function addTo(side, id) {
    const setter = side === "offer" ? setOffer : setReceive;
    setter((prev) => {
      if (prev.includes(id) || prev.length >= MAX_PER_SIDE) return prev;
      return [...prev, id];
    });
  }
  function removeFrom(side, id) {
    const setter = side === "offer" ? setOffer : setReceive;
    setter((prev) => prev.filter((x) => x !== id));
  }

  const lockerIds = [...locker];

  if (page === "privacy") {
    return (
      <LegalPage title="PRIVACY_POLICY" onBack={() => setPage("home")}>
        <LegalP>
          Sprite Exchange doesn't collect, store, or sell any personal information. There's no sign-up, no account,
          and nothing you do here is sent to a server we control.
        </LegalP>
        <LegalH>Your Locker Data</LegalH>
        <LegalP>
          When you star a sprite to save it to My Locker, that information is saved locally in your own browser
          (using browser storage). It stays on your device — we never see it, and it isn't shared with anyone.
          Clearing your browser data will erase it.
        </LegalP>
        <LegalH>Cookies &amp; Tracking</LegalH>
        <LegalP>
          This site does not currently use cookies, analytics, or any third-party tracking scripts. If that ever
          changes — for example, if we add basic visit analytics — this page will be updated first to reflect it.
        </LegalP>
        <LegalH>Children's Privacy</LegalH>
        <LegalP>
          Since we don't collect any personal data from anyone, that includes visitors of any age.
        </LegalP>
        <LegalH>Changes to This Policy</LegalH>
        <LegalP>
          If how this site handles data ever changes, this page will be updated to match. Check back if you're
          unsure.
        </LegalP>
      </LegalPage>
    );
  }

  if (page === "terms") {
    return (
      <LegalPage title="TERMS_OF_SERVICE" onBack={() => setPage("home")}>
        <LegalP>
          By using Sprite Exchange, you agree to the following. If you don't agree, please don't use the site.
        </LegalP>
        <LegalH>What This Site Is</LegalH>
        <LegalP>
          Sprite Exchange is a free, fan-made reference tool for estimating Fortnite sprite trade values. It's built
          by players, for players, and is not an official Epic Games product or service.
        </LegalP>
        <LegalH>Dust Values Are Estimates</LegalH>
        <LegalP>
          All Dust Values shown are community-driven estimates, not official figures from Epic Games. Values can be
          outdated, disputed, or simply wrong. Any trade you make based on this site is entirely your own decision
          and responsibility.
        </LegalP>
        <LegalH>No Warranty</LegalH>
        <LegalP>
          This site is provided "as is," with no guarantees of accuracy, uptime, or fitness for any particular
          purpose. We aren't liable for losses, bad trades, or anything else resulting from using this site.
        </LegalP>
        <LegalH>Ownership</LegalH>
        <LegalP>
          Fortnite, its characters, and related assets belong to Epic Games, Inc. The layout, code, and original
          content of this site belong to its creator.
        </LegalP>
        <LegalH>Changes to These Terms</LegalH>
        <LegalP>
          These terms may be updated as the site grows. Continued use after an update means you accept the revised
          terms.
        </LegalP>
      </LegalPage>
    );
  }

  return (
    <div className="w-full min-h-screen flex flex-col items-center px-4 py-10 gap-8 relative" style={{ background: COLORS.bg }}>
      <style>{`
        @import url('https://fonts.googleapis.com/css2?family=Share+Tech+Mono&display=swap');
        .term-font { font-family: 'Share Tech Mono', monospace; text-transform: uppercase; letter-spacing: 0.5px; }
        @keyframes blink { 0%, 45% { opacity: 1; } 50%, 100% { opacity: 0; } }
        .cursor-blink { animation: blink 1s steps(1) infinite; }
      `}</style>

      {consentModalOpen && (
        <ConsentModal
          onAnswer={answerConsent}
          onOpenPrivacy={() => setPage("privacy")}
          onOpenTerms={() => setPage("terms")}
        />
      )}

      {/* sparse background binary digits */}
      <div className="pointer-events-none fixed inset-0" style={{ zIndex: 0, overflow: "hidden" }}>
        {BITS.map((b) => (
          <span
            key={b.id}
            className="term-font"
            style={{
              position: "absolute",
              top: `${b.top}%`,
              left: `${b.left}%`,
              fontSize: b.size,
              color: COLORS.blue,
              opacity: b.opacity,
              textShadow: `0 0 6px ${COLORS.blue}`,
            }}
          >
            {b.char}
          </span>
        ))}
      </div>

      {/* scanline overlay */}
      <div
        className="pointer-events-none fixed inset-0"
        style={{
          background: "repeating-linear-gradient(0deg, rgba(0,186,255,0.025) 0px, rgba(0,186,255,0.025) 1px, transparent 1px, transparent 3px)",
          zIndex: 0,
        }}
      />

      <div className="text-center max-w-xl relative" style={{ zIndex: 1 }}>
        <div
          className="term-font inline-block px-3 py-1 mb-4"
          style={{ color: COLORS.blue, background: `${COLORS.blue}0d`, border: `1px solid ${COLORS.blue}`, fontSize: 12, textShadow: `0 0 6px ${COLORS.blue}` }}
        >
          [ CHAPTER_7 :: SEASON_4 ]
        </div>
        <h1 className="term-font" style={{ color: COLORS.blue, fontSize: 34, lineHeight: 1.2, textShadow: `0 0 10px ${COLORS.blue}, 0 0 20px ${COLORS.blue}55` }}>
          &gt; SPRITE_EXCHANGE<span className="cursor-blink">_</span>
        </h1>
        <p className="term-font mt-3" style={{ color: COLORS.muted, fontSize: 13, letterSpacing: 0.3 }}>
          // every sprite has a dust_value out of 10 — build both sides of a trade, then run the calculator
        </p>
      </div>

      <div className="w-full max-w-3xl flex flex-col gap-4 relative" style={{ zIndex: 1 }}>
        <div className="flex flex-col md:flex-row items-stretch gap-4">
          <TradePanel title="YOU_OFFER" accent={COLORS.cyan} ids={offer} onRemove={(id) => removeFrom("offer", id)} total={offerTotal} />

          <div className="flex flex-col items-center justify-center gap-1 flex-shrink-0 py-2">
            <span className="term-font" style={{ color: percentColor, fontSize: 20, textShadow: `0 0 8px ${percentColor}` }}>
              {percentLabel}
            </span>
            <svg width="56" height="32" viewBox="0 0 56 32">
              <rect x="4" y="14" width="48" height="3" fill={COLORS.gold} transform={`rotate(${angle} 28 16)`} style={{ transition: "transform 0.4s" }} />
              <rect x="25" y="11" width="6" height="10" fill={COLORS.gold} />
            </svg>
          </div>

          <TradePanel title="YOU_RECEIVE" accent={COLORS.red} ids={receive} onRemove={(id) => removeFrom("receive", id)} total={receiveTotal} />
        </div>
        <div
          className="text-center py-3 term-font"
          style={{ background: COLORS.panel, color: verdictColor, border: `1px solid ${verdictColor}`, fontSize: 14, textShadow: `0 0 6px ${verdictColor}` }}
        >
          {verdict}
        </div>
      </div>

      <div className="w-full max-w-3xl relative" style={{ zIndex: 1 }}>
        <div className="flex items-center gap-2 mb-3">
          <Star size={22} color={COLORS.gold} fill={COLORS.gold} style={{ filter: `drop-shadow(0 0 4px ${COLORS.gold})` }} />
          <h2 className="term-font" style={{ color: COLORS.text, fontSize: 17 }}>MY_LOCKER</h2>
        </div>
        {lockerIds.length === 0 ? (
          <div
            className="term-font text-center p-4"
            style={{ color: COLORS.muted, background: COLORS.panel, border: `1px dashed ${COLORS.muted}`, fontSize: 12 }}
          >
            // star sprites below to save them here
          </div>
        ) : (
          <div className="flex flex-wrap gap-2">
            {lockerIds.map((id) => {
              const v = BY_ID[id];
              const color = variantColor(v.name);
              return (
                <button
                  key={id}
                  onClick={() => addTo("offer", id)}
                  className="flex items-center gap-2 pl-1.5 pr-3 py-1.5"
                  style={{ background: COLORS.panel, border: `1px solid ${color}` }}
                >
                  <SpriteVisual image={v.image} base={v.base} color={color} size={28} />
                  <span className="term-font" style={{ color: COLORS.text, fontSize: 13 }}>{v.label}</span>
                  <span className="term-font" style={{ color: COLORS.gold, fontSize: 12 }}>{v.dust}</span>
                </button>
              );
            })}
          </div>
        )}
      </div>

      <div className="w-full max-w-3xl relative" style={{ zIndex: 1 }}>
        <h2 className="term-font mb-3" style={{ color: COLORS.text, fontSize: 17 }}>ALL_SPRITES</h2>
        <div className="grid grid-cols-2 sm:grid-cols-3 gap-3">
          {SPRITES.map((s) => (
            <SpriteCard
              key={s.slug}
              sprite={s}
              selectedIdx={selectedIdx[s.slug]}
              onSelect={onSelect}
              locker={locker}
              toggleLocker={toggleLocker}
              addTo={addTo}
            />
          ))}
        </div>
      </div>

      <footer className="w-full max-w-3xl relative pt-4" style={{ zIndex: 1, borderTop: `1px dashed ${COLORS.muted}44` }}>
        <p style={{ color: COLORS.muted, fontSize: 11, letterSpacing: 0.2, textAlign: "center", lineHeight: 1.6, fontFamily: "'Share Tech Mono', monospace" }}>
          This is a fan-built project made by players, for players. Sprite Exchange has no connection to Epic Games —
          we're not sponsored, endorsed, or officially recognized by them in any way. All Fortnite names, characters,
          and imagery referenced here remain the property of Epic Games, Inc.
        </p>
        <div className="flex items-center justify-center gap-4 mt-3">
          <button
            onClick={() => setPage("privacy")}
            className="term-font"
            style={{ color: COLORS.blue, fontSize: 11, background: "none", border: "none", cursor: "pointer", textShadow: `0 0 4px ${COLORS.blue}` }}
          >
            PRIVACY_POLICY
          </button>
          <span style={{ color: COLORS.muted }}>·</span>
          <button
            onClick={() => setPage("terms")}
            className="term-font"
            style={{ color: COLORS.blue, fontSize: 11, background: "none", border: "none", cursor: "pointer", textShadow: `0 0 4px ${COLORS.blue}` }}
          >
            TERMS_OF_SERVICE
          </button>
          <span style={{ color: COLORS.muted }}>·</span>
          <button
            onClick={() => setConsentModalOpen(true)}
            className="term-font"
            style={{ color: COLORS.blue, fontSize: 11, background: "none", border: "none", cursor: "pointer", textShadow: `0 0 4px ${COLORS.blue}` }}
          >
            STORAGE_PREFERENCES
          </button>
        </div>
      </footer>
    </div>
  );
}
